clean_output:
    If `directory` is a file, it will be ignored.
"""
checksums = {}
for root, dirs, files in os.walk(directory):
    for fn in files:
        if fn in blacklist:
            continue
        full_path = os.path.join(root, fn)
        with open(full_path, 'rb') as f:
            checksums[fn] = hashlib.md5(f.read()).hexdigest()
return checksums
